def split_csv_line(line: str, delimiter: str = ",") -> List[str]:
    """Split a single CSV line into fields, honouring double quotes.

    - Quoted fields may contain the delimiter and escaped quotes ("").
    - Unquoted empty fields are dropped; quoted empty fields are kept.
    - A trailing delimiter does not produce an extra empty field.
    """
    if len(delimiter) != 1 or delimiter == '"':
        raise ValueError("delimiter must be a single character other than a double quote")
    fields: List[str] = []
    pos, end = 0, len(line)
